# =============================================================================
# Writes dual_hit.jl: the ray–surface intersection of a height field whose
# heights carry ForwardDiff Duals (one partial per node), as the GENERIC root
# computed it before the height fast path took Duals (VisualGeometryToolkitCore
# at hoists-09-next 4c9252d6: `intersection` of a MappedSurface with Dual
# heights was `_mapped_intersection`, the 2 × 2 LM from the plane hit, then the
# implicit-function step). The board is RadiometricCamera's: 25 nodes on the
# page chart [0, 1] × [0, −1], placed with side 1 m, posed 1.2 m away; the rays
# leave a camera 1 m in front of it. The test (test/mapped_surface_tests.jl)
# rebuilds the surface and compares `intersection`'s value and partials.
#
# Every value is printed with `repr` (exact round trip). Run in the package's
# test environment:
#
#   julia --project=VisualGeometryToolkitCore/test <this file> <output path>
#
# Not discovered by the test runner (no `_tests.jl` suffix).
# =============================================================================

using StaticArrays, LinearAlgebra, Random, ForwardDiff
using Rotations: RotMatrix, RotXYZ
using VisualGeometryToolkitCore
using VisualGeometryToolkitCore: grid_nodes, with_parameters

const OUT = length(ARGS) >= 1 ? ARGS[1] : joinpath(@__DIR__, "dual_hit.jl")

include(joinpath(@__DIR__, "dual_hit_surface.jl"))
rng = Xoshiro(7)
heights = 0.004 .* randn(rng, 25)
rays = map(1:16) do _
    o = SVector(0.25randn(rng), 0.25randn(rng), 0.0)
    d = normalize(SVector(0.12randn(rng), 0.12randn(rng), -1.0))
    (dual_hit_pose(o + SVector(0.0, 0.0, 1.0)), SMatrix{3, 3}(dual_hit_rotation()) * d)
end
s = dual_hit_surface(dual_hit_heights(heights))
hits = [VisualGeometryToolkitCore.Cameras._mapped_intersection(s, o, d) for (o, d) in rays]

open(OUT, "w") do io
    println(io, "# GENERATED by generate_dual_hit.jl from VisualGeometryToolkitCore at hoists-09-next 4c9252d6 (the generic root). Do not edit.")
    println(io, "const DUAL_HIT_REFERENCE = (")
    println(io, "    heights = ", repr(heights), ",")
    println(io, "    origins = [", join((repr(Vector(o)) for (o, _) in rays), ", "), "],")
    println(io, "    directions = [", join((repr(Vector(d)) for (_, d) in rays), ", "), "],")
    println(io, "    t = ", repr([ForwardDiff.value(t) for (t, _) in hits]), ",")
    println(io, "    dt_dh = [", join((repr(collect(ForwardDiff.partials(t).values)) for (t, _) in hits), ",\n        "), "],")
    println(io, ")")
end
